-- Db2 CREATE TABLE ... AS and CREATE TABLE ... LIKE forms.
-- https://www.ibm.com/docs/en/db2/11.5?topic=statements-create-table

CREATE TABLE t_as_bracketed AS (SELECT * FROM s);

CREATE TABLE t_as_no_data AS (SELECT * FROM s) WITH NO DATA;

CREATE TABLE t_as_data AS (SELECT * FROM s) WITH DATA;

CREATE TABLE t_as_columns (a, b) AS (SELECT x, y FROM s) WITH NO DATA;

CREATE TABLE t_as_one_column (a) AS (SELECT x FROM s) WITH DATA;

CREATE TABLE t_as_data_capture AS (SELECT * FROM s) WITH NO DATA DATA CAPTURE CHANGES;

CREATE TABLE t_like LIKE s;

CREATE TABLE t_like_including LIKE s INCLUDING COLUMN DEFAULTS;

CREATE TABLE t_like_excluding LIKE s EXCLUDING COLUMN DEFAULTS;

CREATE TABLE t_like_identity LIKE s INCLUDING IDENTITY COLUMN ATTRIBUTES;

CREATE TABLE t_like_no_identity LIKE s EXCLUDING IDENTITY COLUMN ATTRIBUTES;

CREATE TABLE t_like_all LIKE s
    INCLUDING COLUMN DEFAULTS
    INCLUDING IDENTITY COLUMN ATTRIBUTES;

CREATE TABLE t_like_tablespace LIKE s IN ts;

CREATE TABLE t_like_compress LIKE s INCLUDING COLUMN DEFAULTS COMPRESS YES;

CREATE TABLE t_mqt (a) AS (SELECT * FROM s) DATA INITIALLY DEFERRED REFRESH DEFERRED;

CREATE TABLE t_mqt_immediate (a) AS (SELECT * FROM s) REFRESH IMMEDIATE;

CREATE TABLE t_mqt_options (a) AS (SELECT * FROM s)
    REFRESH IMMEDIATE
    ENABLE QUERY OPTIMIZATION;

CREATE TABLE t_mqt_system (a) AS (SELECT * FROM s) MAINTAINED BY SYSTEM;

CREATE TABLE t_mqt_user (a) AS (SELECT * FROM s) MAINTAINED BY USER;

CREATE TABLE t_mqt_no_data (a) AS (SELECT * FROM s) WITH NO DATA;

CREATE TABLE t_staging (a) FOR mqt PROPAGATE IMMEDIATE;
